  ST.defineDungeon({ id: 'khan_arena', n: 'Арена Стойбища', ic: '🏟️', lv: 56, floors: 2, bio: 'ash', col: '#e06a40', d: 'Круглая арена посреди степи, обнесённая кольцом кольев. На трибунах — все кланы. Внизу — песок, мокрый от пота и пролитого кумыса.', pool: ['arena_wolf', 'fang_guard', 'banner_bearer', 'arena_wolf'], mini: 'war_champion', boss: 'khan_crimson', need: 'tur_plain', gate: '#pending', lockHint: 'Сначала прочтите главу «Арена Стойбища».' });
  D.INTROS.khan_arena = [['bg', 'battlefield'], ['n', `Песок арены горячий, как печная плита. Трибуны гудят: тысячи голосов сливаются в один ровный рокот. С флагштоков свисают чёрные знамёна с волчьим клыком.`], ['m', `Не смотри на них. Смотри на меня. Или на песок. Или на пирог в моём кармане.`, 'n'], ['h', `У тебя в кармане пирог?`, 'n'], ['m', `Нет. Это для твоей мотивации.`, 'h']];

